CREATE PROCEDURE sp_SearchEmployees
    @Department NVARCHAR(50) = NULL,
    @MinSalary DECIMAL(10,2) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX) = N'
        SELECT EmployeeID, FirstName, LastName, Department, Salary
        FROM Employees
        WHERE 1 = 1';

    DECLARE @Params NVARCHAR(MAX) = N'
        @Department NVARCHAR(50),
        @MinSalary DECIMAL(10,2)';

    IF @Department IS NOT NULL
        SET @SQL += N' AND Department = @Department';

    IF @MinSalary IS NOT NULL
        SET @SQL += N' AND Salary >= @MinSalary';

    SET @SQL += N' ORDER BY Salary DESC;';

    EXEC sp_executesql @SQL, @Params, @Department, @MinSalary;
END;

-- Examples:
-- EXEC sp_SearchEmployees @Department = 'Engineering';
-- EXEC sp_SearchEmployees @MinSalary = 90000;
-- EXEC sp_SearchEmployees 'Engineering', 90000;
